        public static IEnumerator CreateCandidate(string sourceTag,string candidateTag)
        {
            RequireTag(sourceTag);RequireTag(candidateTag);
            if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||VistaManager.HasActiveTask()||Terrain.activeTerrains.Length!=0)
                throw new InvalidOperationException("Stopped isolated Editor without active terrain or Vista task required.");
            string sourcePath=Root+"VisualCandidates/"+sourceTag+"/Shared Dragon Kingdom.prefab";
            string folder=Root+"ReviewCandidates/"+candidateTag,privateFolder=Root+"PrivateLicensedEnvironment/DerivedVista/"+candidateTag;
            if(Directory.Exists(Io(folder))||Directory.Exists(Io(privateFolder)))throw new InvalidOperationException("Fresh outer candidate/private graph tag required; existing outputs are never overwritten.");
            var inner=AssetDatabase.LoadAssetAtPath<GameObject>(sourcePath);var rounded=AssetDatabase.LoadAssetAtPath<GameObject>(Rounded);
            if(inner==null||rounded==null)throw new InvalidOperationException("Actual accepted inner candidate and configured rounded Vista source are required.");
            var innerTiles=ReadInner(inner);
            var watched=Snapshot(new[]{sourcePath,Rounded,Root+"Prefabs/Shared Dragon Kingdom.prefab"});
            var receipt=new Receipt{source=sourcePath,folder=folder,prefab=folder+"/Outer Vista Band.prefab",privateGraphs=privateFolder,preservedPaths=watched.Keys.OrderBy(p=>p,StringComparer.Ordinal).ToArray(),preservedAssets=watched.OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>new PreservedAsset{path=p.Key,sha256=p.Value}).ToArray()};
            LastReceipt=receipt;
            Directory.CreateDirectory(Io(folder+"/Terrain"));Directory.CreateDirectory(Io(privateFolder));AssetDatabase.Refresh();
            var scene=EditorSceneManager.NewPreviewScene();GameObject author=null,output=null;VistaManager manager=null;
            var grids=new List<Grid>();var observed=new HashSet<ITile>();Exception observationError=null;bool generating=false;
            VistaManager.TexturePopulatedHandler observe=(sender,tile,texture)=>
            {
                if(sender!=manager)return;
                try
                {
                    if(!grids.Any(g=>ReferenceEquals(g.tile,tile)))throw new InvalidOperationException("Vista attempted to populate an unowned/original tile.");
                    receipt.heightCallbacks++;if(!observed.Add(tile))throw new InvalidOperationException("Duplicate height population for an outer tile.");
                }
                catch(Exception e){observationError=e;}
            };
            VistaManager.heightMapPopulated+=observe;
            try
            {
                author=(GameObject)PrefabUtility.InstantiatePrefab(rounded);SceneManager.MoveGameObjectToScene(author,scene);author.name="Temporary actual Vista outer authoring";
                PrefabUtility.UnpackPrefabInstance(author,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);
                manager=author.GetComponentInChildren<VistaManager>(true);if(manager==null||author.GetComponentsInChildren<VistaManager>(true).Length!=1)throw new InvalidOperationException("Exactly one configured real Vista manager required.");
                // The original TerrainData assets are NEVER passed to the vendor.
                foreach(var old in author.GetComponentsInChildren<Terrain>(true))UnityEngine.Object.DestroyImmediate(old.gameObject);
                if(author.GetComponentsInChildren<Terrain>(true).Length!=0)throw new InvalidOperationException("Original authoring terrain removal failed.");
                foreach(string name in new[]{"m_beforeGeneratingUnityCallback","m_afterGeneratingUnityCallback"})
                {
                    var f=typeof(VistaManager).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance);
                    if(f==null)throw new InvalidOperationException("Configured Vista callback schema changed.");
                    if(f.GetValue(manager)==null)f.SetValue(manager,new UnityEvent());
                }
                CloneAndExtendBiomes(author,manager,privateFolder,receipt);
                output=new GameObject("Outer Vista Band - scenery candidate");SceneManager.MoveGameObjectToScene(output,scene);
                var template=innerTiles[0];int resolution=template.terrainData.heightmapResolution;
                for(int iz=0;iz<4;iz++)for(int ix=0;ix<4;ix++)
                {
                    if(ix>0&&ix<3&&iz>0&&iz<3)continue;
                    var data=new TerrainData{name="Outer Vista "+ix+" "+iz,heightmapResolution=resolution,alphamapResolution=512,baseMapResolution=512,size=new Vector3(Widths[ix],Height,Widths[iz])};
                    string path=folder+"/Terrain/Outer "+ix+" "+iz+".asset";AssetDatabase.CreateAsset(data,path);
                    var go=Terrain.CreateTerrainGameObject(data);SceneManager.MoveGameObjectToScene(go,scene);go.name="Vista outer scenery "+ix+" "+iz;go.transform.SetParent(output.transform,false);go.transform.position=new Vector3(X[ix],BaseY,Z[iz]);
                    var terrain=go.GetComponent<Terrain>();
                    terrain.materialTemplate=template.materialTemplate;terrain.drawInstanced=template.drawInstanced;terrain.heightmapPixelError=template.heightmapPixelError;terrain.basemapDistance=template.basemapDistance;
                    terrain.shadowCastingMode=template.shadowCastingMode;terrain.allowAutoConnect=false;terrain.groupingID=template.groupingID;
                    var tile=go.AddComponent<TerrainTile>();tile.managerId=manager.id;
                    grids.Add(new Grid{terrain=terrain,tile=tile,data=data,receipt=new TileReceipt{path=path,position=go.transform.position,size=data.size,resolution=resolution}});
                }
                if(grids.Count!=12)throw new InvalidOperationException("Exactly twelve outer tiles required.");
                var generation=manager.Generate(grids.Select(g=>(ITile)g.tile).ToArray());generating=true;double started=EditorApplication.timeSinceStartup;
                while(!generation.isCompleted)
                {
                    if(EditorApplication.timeSinceStartup-started>900)throw new TimeoutException("Real Vista twelve-tile outer generation timed out.");
                    if(observationError!=null)throw observationError;
                    yield return null;
                }
                generating=false;if(observationError!=null)throw observationError;
                receipt.uniqueHeightTiles=observed.Count;receipt.originalInnerNotGenerated=receipt.heightCallbacks==12&&observed.Count==12;
                if(!receipt.originalInnerNotGenerated)throw new InvalidOperationException("Twelve distinct real outer height callbacks required; source terrain must never be populated.");
                foreach(var g in grids)
                {
                    if(g.data.size!=g.receipt.size||g.data.heightmapResolution!=resolution)throw new InvalidOperationException("Vendor changed explicit outer tile dimensions/resolution.");
                    g.raw=g.data.GetHeights(0,0,resolution,resolution);g.heights=(float[,])g.raw.Clone();g.receipt.generatedHeightHash=HeightHash(g.raw);
                }
                CoordinateNewHeights(grids,innerTiles);
                foreach(var g in grids)
                {
                    g.data.SetHeights(0,0,g.heights);g.terrain.Flush();
                    DragonKingdomWorldVisualMigration.RepairOuterTerrainAppearance(g.data,candidateTag);
                    EditorUtility.SetDirty(g.data);AssetDatabase.SaveAssetIfDirty(g.data);
                    g.receipt.coordinatedHeightHash=HeightHash(g.data.GetHeights(0,0,resolution,resolution));
                    UnityEngine.Object.DestroyImmediate(g.tile); // Runtime scenery has no Editor generation authority.
                }
                LinkOuterNeighbors(grids.Select(g=>g.terrain).ToArray());
                receipt.seams=ValidateAgainstInner(inner,output);receipt.terrains=grids.Select(g=>g.receipt).ToArray();receipt.validationIssues=receipt.seams.issues;
                if(receipt.validationIssues.Length!=0)throw new InvalidOperationException("Actual outer seam/bed validation rejected: "+string.Join(" | ",receipt.validationIssues));
                if(PrefabUtility.SaveAsPrefabAsset(output,receipt.prefab)==null)throw new InvalidOperationException("Outer-only prefab save failed.");
                var graphs=Enumerable.Range(0,receipt.clonedTerrainGraphs).Select(i=>privateFolder+"/Terrain graph "+i+".asset")
                    .Concat(Enumerable.Range(0,receipt.clonedMaskGraphs).Select(i=>privateFolder+"/Mask graph "+i+".asset"))
                    .Concat(new[]{privateFolder+"/Vendor constant coastal bed.asset",privateFolder+"/Vendor smooth coastal falloff.asset"});
                // Includes genuine binary TerrainData dependencies via Unity's
                // asset database; the Python retention tool never guesses those.
                receipt.outputDependencies=Snapshot(new[]{receipt.prefab}.Concat(graphs)).OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>new PreservedAsset{path=p.Key,sha256=p.Value}).ToArray();
                receipt.status="MEASURED_SCENERY_CANDIDATE_REQUIRES_RENDER_AND_WORLD_ATTACHMENT_REVIEW";
            }
            finally
            {
                VistaManager.heightMapPopulated-=observe;
                if(generating&&VistaManager.HasActiveTask())VistaManager.CancelActiveGenerateTask();
                if(author!=null){foreach(var biome in author.GetComponentsInChildren<LocalProceduralBiome>(true))biome.CleanUp();UnityEngine.Object.DestroyImmediate(author);}
                if(output!=null)UnityEngine.Object.DestroyImmediate(output);
                if(scene.IsValid())EditorSceneManager.ClosePreviewScene(scene);
                receipt.temporaryObjectsRemoved=!scene.IsValid()||!scene.isLoaded;
                receipt.sourceBytesPreserved=watched.All(p=>File.Exists(Io(p.Key))&&Hash(File.ReadAllBytes(Io(p.Key)))==p.Value);
                if(receipt.status=="IN_PROGRESS")receipt.status="FAILED_OR_INCOMPLETE_OUTER_SCENERY";
                string json=JsonUtility.ToJson(receipt,true);File.WriteAllText(Io(folder+"/Outer Vista Receipt.json"),json);
                string evidence=Arg("-tsDragonOutput","Logs/TruckSports/DragonKingdom");Directory.CreateDirectory(Io(evidence));File.WriteAllText(Io(Path.Combine(evidence,"outer-vista-"+candidateTag+".json")),json);
                if(!receipt.sourceBytesPreserved)throw new InvalidOperationException("Outer generation altered original inner/source/canonical asset bytes.");
            }
        }

        static void CloneAndExtendBiomes(GameObject author,VistaManager manager,string folder,Receipt receipt)
        {
            var graphs=new Dictionary<TerrainGraph,TerrainGraph>();var masks=new Dictionary<BiomeMaskGraph,BiomeMaskGraph>();int baseCount=0;
            foreach(var biome in author.GetComponentsInChildren<LocalProceduralBiome>(true))
            {
                var source=biome.terrainGraph;if(source==null)throw new InvalidOperationException("All actual rounded biomes require their source graph.");
                bool full=Path.GetFileNameWithoutExtension(AssetDatabase.GetAssetPath(source)).StartsWith("Full coverage",StringComparison.Ordinal);
                if(!graphs.TryGetValue(source,out var owned))
                {owned=UnityEngine.Object.Instantiate(source);owned.OnBeforeSerialize();AssetDatabase.CreateAsset(owned,folder+"/Terrain graph "+graphs.Count+".asset");graphs.Add(source,owned);}
                biome.terrainGraph=owned;
                var mask=biome.biomeMaskGraph;
                if(mask!=null)
                {
                    if(!masks.TryGetValue(mask,out var copy)){copy=UnityEngine.Object.Instantiate(mask);copy.OnBeforeSerialize();AssetDatabase.CreateAsset(copy,folder+"/Mask graph "+masks.Count+".asset");masks.Add(mask,copy);}
                    biome.biomeMaskGraph=copy;
                }
                if(full){biome.anchors=Rectangle(-2700,-1900,2700,3500);baseCount++;}
            }
            if(baseCount!=1)throw new InvalidOperationException("One exact original full-coverage base biome required.");
            var coast=ScriptableObject.CreateInstance<TerrainGraph>();coast.Reset();coast.name="Vendor constant outer ocean bed";
            var constant=new ConstantHeightNode{targetHeight=Bed-BaseY};var terminal=new HeightOutputNode();coast.AddNode(constant);coast.AddNode(terminal);
            coast.AddEdge(new Edge{outputSlot=new SlotRef(constant.id,constant.outputSlot.id),inputSlot=new SlotRef(terminal.id,terminal.inputSlot.id)});coast.OnBeforeSerialize();AssetDatabase.CreateAsset(coast,folder+"/Vendor constant coastal bed.asset");
            var strips=new[]{Rectangle(-2600,-1800,-2336,3400),Rectangle(2336,-1800,2600,3400),Rectangle(-2600,-1800,2600,-1536),Rectangle(-2600,3136,2600,3400)};
            var smooth=CreateSmoothMask();AssetDatabase.CreateAsset(smooth,folder+"/Vendor smooth coastal falloff.asset");
            for(int i=0;i<strips.Length;i++)
            {
                var biome=LocalProceduralBiome.CreateInstanceInScene(manager);biome.Reset();biome.name="Outer coastal bed "+i;biome.terrainGraph=coast;
                biome.dataMask=BiomeDataMask.HeightMap;biome.baseResolution=513;biome.anchors=strips[i];biome.order=10000+i;biome.falloffDirection=FalloffDirection.Outer;biome.falloffDistance=600;biome.biomeMaskGraph=smooth;
                var blend=biome.blendOptions;blend.heightMapBlendMode=BiomeBlendOptions.HeightBlendMode.Replace;biome.blendOptions=blend;
            }
            receipt.clonedTerrainGraphs=graphs.Count;receipt.clonedMaskGraphs=masks.Count;
        }

        static BiomeMaskGraph CreateSmoothMask()
        {
            var graph=ScriptableObject.CreateInstance<BiomeMaskGraph>();graph.Reset();var input=new InputNode{inputName=GraphConstants.BIOME_MASK_INPUT_NAME};var curve=new CurveNode{curve=AnimationCurve.EaseInOut(0,0,1,1)};var output=new OutputNode{outputName=GraphConstants.BIOME_MASK_OUTPUT_NAME};
            graph.AddNode(input);graph.AddNode(curve);graph.AddNode(output);graph.AddEdge(new Edge{outputSlot=new SlotRef(input.id,input.outputSlot.id),inputSlot=new SlotRef(curve.id,curve.inputSlot.id)});graph.AddEdge(new Edge{outputSlot=new SlotRef(curve.id,curve.outputSlot.id),inputSlot=new SlotRef(output.id,output.inputSlot.id)});graph.OnBeforeSerialize();return graph;
        }
        static Vector3[] Rectangle(float x0,float z0,float x1,float z1)=>new[]{new Vector3(x0,0,z0),new Vector3(x1,0,z0),new Vector3(x1,0,z1),new Vector3(x0,0,z1)};

        static void CoordinateNewHeights(List<Grid> grids,Terrain[] inner)
        {
            var edges=new Dictionary<string,List<Vertex>>();
            foreach(var g in grids)
            {
                int n=g.receipt.resolution;var p=g.receipt.position;var size=g.receipt.size;
                for(int z=0;z<n;z++)for(int x=0;x<n;x++)
                {
                    float wx=p.x+size.x*x/(n-1),wz=p.z+size.z*z/(n-1),raw=g.heights[z,x];RequireFinite(raw);
                    float px=Mathf.Clamp(wx,-1600,1600),pz=Mathf.Clamp(wz,-800,2400),distance=Vector2.Distance(new Vector2(wx,wz),new Vector2(px,pz));
                    if(distance<Collar)
                    {
                        float source=SampleInner(inner,px,pz),weight=1-Mathf.SmoothStep(0,1,distance/Collar);
                        g.heights[z,x]=Mathf.Lerp(raw,(source-BaseY)/Height,weight);g.receipt.collarSamples++;
                    }
                    if(x==0||z==0||x==n-1||z==n-1)
                    {
                        string key=Key(wx,wz);if(!edges.TryGetValue(key,out var vertices)){vertices=new List<Vertex>();edges.Add(key,vertices);}
                        vertices.Add(new Vertex{grid=g,x=x,z=z,worldX=wx,worldZ=wz});
                    }
                }
            }
            foreach(var vertices in edges.Values)
            {
                if(vertices.Count<2)continue;
                var first=vertices[0];float shared=OnInnerBoundary(first.worldX,first.worldZ)?(SampleInner(inner,first.worldX,first.worldZ)-BaseY)/Height:vertices.Average(v=>v.grid.heights[v.z,v.x]);
                foreach(var v in vertices){v.grid.heights[v.z,v.x]=shared;v.grid.receipt.seamSamples++;}
            }
            foreach(var g in grids)
            {
                var r=g.receipt;r.minimum=float.PositiveInfinity;r.maximum=float.NegativeInfinity;int n=r.resolution;
                for(int z=0;z<n;z++)for(int x=0;x<n;x++)
                {
                    float value=g.heights[z,x];RequireFinite(value);if(value<0||value>1)throw new InvalidOperationException("Outer coordination exceeds actual600m terrain range.");
                    r.minimum=Mathf.Min(r.minimum,value*Height+BaseY);r.maximum=Mathf.Max(r.maximum,value*Height+BaseY);r.maximumCoordination=Mathf.Max(r.maximumCoordination,Mathf.Abs(value-g.raw[z,x])*Height);
                    float wx=r.position.x+r.size.x*x/(n-1),wz=r.position.z+r.size.z*z/(n-1);float d=Vector2.Distance(new Vector2(wx,wz),new Vector2(Mathf.Clamp(wx,-1600,1600),Mathf.Clamp(wz,-800,2400)));
                    if(d>=Collar&&x>0&&x<n-1&&z>0&&z<n-1)
                    {if(value!=g.raw[z,x])throw new InvalidOperationException("Untouched genuine Vista interior changed outside collar/seams.");r.unchangedInteriorSamples++;}
                }
            }
        }

        // Does not mutate either prefab/instance. The source can be the actual
