        public static SeamReceipt ValidateAgainstInner(GameObject actualInner,GameObject outer)
            =>ValidateCoreAgainstOuter(ReadInner(actualInner),outer);

        [Serializable]public sealed class CurrentCoreCoordination
        {
            public string scope="OWNED_VISTA_OUTER_COPIES_EXISTING160M_COLLAR_HEIGHT_DELTA_ONLY_ORIGINAL_CORE_AND_SOURCES_UNCHANGED_NOT_RENDER_OR_WORLD_ACCEPTANCE",sourceInner,sourceOuter;
            public float collarMetres=Collar;public bool coreHeightmapsExact,originalSourcesExact,nonHeightPayloadExact,beyondCollarExact,passed;public SeamReceipt before,after;public CurrentCoreTile[] tiles;
        }
        [Serializable]public sealed class CurrentCoreTile
        {public string candidate,beforeHeightHash,afterHeightHash;public int changedSamples,untouchedBeyondCollarSamples;public float maximumHeightDelta;}
        public static CurrentCoreCoordination LastCurrentCoreCoordination{get;private set;}
        public static float CurrentCoreCollarHeight(float existingWorldHeight,float priorInnerHeight,float currentInnerHeight,float distance)
        {
            if(!float.IsFinite(existingWorldHeight)||!float.IsFinite(priorInnerHeight)||!float.IsFinite(currentInnerHeight)||!float.IsFinite(distance)||distance<0)throw new ArgumentException("Finite actual source/current heights and nonnegative measured collar distance required.");
            if(distance>=Collar||priorInnerHeight==currentInnerHeight)return existingWorldHeight;
            return existingWorldHeight+(currentInnerHeight-priorInnerHeight)*(1-Mathf.SmoothStep(0,1,distance/Collar));
        }
        static string CurrentCoreNonHeightHash(TerrainData data)
        {
            using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream))
            {
                writer.Write(data.size.x);writer.Write(data.size.y);writer.Write(data.size.z);writer.Write(data.heightmapResolution);writer.Write(data.alphamapWidth);writer.Write(data.alphamapHeight);writer.Write(data.holesResolution);
                foreach(float value in data.GetAlphamaps(0,0,data.alphamapWidth,data.alphamapHeight))writer.Write(value);foreach(bool value in data.GetHoles(0,0,data.holesResolution,data.holesResolution))writer.Write(value);foreach(var layer in data.terrainLayers)writer.Write(AssetDatabase.GetAssetPath(layer));return Hash(stream.ToArray());
            }
        }
