            var core=ValidateInner(world.GetComponentsInChildren<Terrain>(true).Where(t=>!t.transform.IsChildOf(outer.transform)).ToArray());var oldInner=AssetDatabase.LoadAssetAtPath<GameObject>(originalInner);var oldOuter=AssetDatabase.LoadAssetAtPath<GameObject>(originalOuter);var reference=ReadInner(oldInner);
            if(oldOuter==null||ValidateAgainstInner(oldInner,oldOuter).issues.Length!=0)throw new InvalidOperationException("Original measured Vista inner/outer source pair must still pass its unchanged seam contract.");
            var copies=outer.GetComponentsInChildren<Terrain>(true);if(copies.Length!=12||copies.Select(t=>t.terrainData).Distinct().Count()!=12||copies.Any(t=>t.terrainData==null||!AssetDatabase.GetAssetPath(t.terrainData).StartsWith(candidateFolder+"/Terrain/Palette/Outer ",StringComparison.Ordinal)||t.GetComponent<TerrainCollider>()?.terrainData!=t.terrainData))throw new InvalidOperationException("Every outer Terrain and matching TerrainCollider must use its unique existing owned palette copy.");
            var coreHashes=core.ToDictionary(t=>t,t=>HeightHash(t.terrainData.GetHeights(0,0,513,513)));var protectedPaths=new[]{originalInner,originalOuter}.Concat(reference.Concat(oldOuter.GetComponentsInChildren<Terrain>(true)).Select(t=>AssetDatabase.GetAssetPath(t.terrainData))).SelectMany(p=>new[]{p,p+".meta"}).Distinct().ToDictionary(p=>p,p=>Hash(File.ReadAllBytes(Io(p))));var other=copies.ToDictionary(t=>t,t=>CurrentCoreNonHeightHash(t.terrainData));
            var proof=LastCurrentCoreCoordination=new CurrentCoreCoordination{sourceInner=originalInner,sourceOuter=originalOuter,before=ValidateCoreAgainstOuter(core,outer),beyondCollarExact=true};var records=new List<CurrentCoreTile>();
            try
            {
                foreach(var terrain in copies)
                {
                    var data=terrain.terrainData;int n=data.heightmapResolution;var before=data.GetHeights(0,0,n,n);var heights=(float[,])before.Clone();var position=terrain.transform.position;var size=data.size;var row=new CurrentCoreTile{candidate=AssetDatabase.GetAssetPath(data),beforeHeightHash=HeightHash(before)};records.Add(row);
                    for(int z=0;z<n;z++)for(int x=0;x<n;x++)
                    {
                        float wx=position.x+size.x*x/(n-1),wz=position.z+size.z*z/(n-1),px=Mathf.Clamp(wx,-1600,1600),pz=Mathf.Clamp(wz,-800,2400),distance=Vector2.Distance(new Vector2(wx,wz),new Vector2(px,pz));
                        if(distance>=Collar){row.untouchedBeyondCollarSamples++;continue;}
                        float existing=position.y+before[z,x]*size.y,changed=CurrentCoreCollarHeight(existing,SampleInner(reference,px,pz),SampleInner(core,px,pz),distance);if(changed==existing)continue;float normalized=(changed-position.y)/size.y;RequireFinite(normalized);if(normalized<0||normalized>1)throw new InvalidOperationException("Actual current-core seam delta exceeds source terrain range.");heights[z,x]=normalized;if(heights[z,x]!=before[z,x]){row.changedSamples++;row.maximumHeightDelta=Mathf.Max(row.maximumHeightDelta,Mathf.Abs(heights[z,x]-before[z,x])*size.y);}
                    }
                    data.SetHeights(0,0,heights);terrain.Flush();EditorUtility.SetDirty(data);AssetDatabase.SaveAssetIfDirty(data);var actual=data.GetHeights(0,0,n,n);row.afterHeightHash=HeightHash(actual);
                    for(int z=0;z<n;z++)for(int x=0;x<n;x++){float wx=position.x+size.x*x/(n-1),wz=position.z+size.z*z/(n-1);if(Vector2.Distance(new Vector2(wx,wz),new Vector2(Mathf.Clamp(wx,-1600,1600),Mathf.Clamp(wz,-800,2400)))>=Collar&&actual[z,x]!=before[z,x])proof.beyondCollarExact=false;}
