            finally
            {
                proof.tiles=records.ToArray();proof.coreHeightmapsExact=coreHashes.All(p=>HeightHash(p.Key.terrainData.GetHeights(0,0,513,513))==p.Value);proof.originalSourcesExact=protectedPaths.All(p=>Hash(File.ReadAllBytes(Io(p.Key)))==p.Value);proof.nonHeightPayloadExact=other.All(p=>CurrentCoreNonHeightHash(p.Key.terrainData)==p.Value);proof.passed=proof.tiles.Length==12&&proof.after!=null&&proof.after.issues.Length==0&&proof.coreHeightmapsExact&&proof.originalSourcesExact&&proof.nonHeightPayloadExact&&proof.beyondCollarExact;
            }
            if(!proof.passed)throw new InvalidOperationException("Owned current-core outer collar did not preserve original source/core/non-height/far-interior or unchanged.04m seam acceptance: "+JsonUtility.ToJson(proof));return proof;
        }

        // Explicit core identity set supports a later world with all16 terrains
        // attached. It does not relax the factory's exact-four ReadInner guard.
        public static SeamReceipt ValidateCoreAgainstOuter(Terrain[] exactFourInner,GameObject outer)
        {
            var inner=ValidateInner(exactFourInner);if(outer==null)throw new ArgumentNullException(nameof(outer));var tiles=outer.GetComponentsInChildren<Terrain>(true);var result=new SeamReceipt();var issues=new List<string>();
            if(tiles.Length!=12)issues.Add("Exactly twelve outer Terrain components required.");
            if(outer.GetComponentsInChildren<VistaManager>(true).Length!=0||outer.GetComponentsInChildren<LocalProceduralBiome>(true).Length!=0||outer.GetComponentsInChildren<TerrainTile>(true).Length!=0)issues.Add("Output scenery must not retain generation components.");
            var vertices=new Dictionary<string,List<float>>();var cells=new HashSet<string>();
            foreach(var t in tiles)
            {
                var p=t.transform.position;var data=t.terrainData;if(data==null){issues.Add("Missing actual outer TerrainData.");continue;}var s=data.size;
                int ix=Array.FindIndex(X,v=>Mathf.Abs(v-p.x)<.001f),iz=Array.FindIndex(Z,v=>Mathf.Abs(v-p.z)<.001f);
                if(ix<0||iz<0||(ix>0&&ix<3&&iz>0&&iz<3)||!cells.Add(ix+":"+iz)||Mathf.Abs(p.y-BaseY)>.001f||Mathf.Abs(s.x-Widths[Mathf.Max(0,ix)])>.001f||Mathf.Abs(s.z-Widths[Mathf.Max(0,iz)])>.001f||Mathf.Abs(s.y-Height)>.001f||t.transform.lossyScale!=Vector3.one||Quaternion.Angle(t.transform.rotation,Quaternion.identity)>.001f)
                    issues.Add("Outer tile origin/size/transform does not match bounded12cell plan: "+t.name);
                if(t.GetComponent<TerrainCollider>()?.terrainData!=data)issues.Add("Real matching TerrainCollider required: "+t.name);
                int n=data.heightmapResolution;var heights=data.GetHeights(0,0,n,n);
                for(int z=0;z<n;z++)for(int x=0;x<n;x++)
                {
                    float value=heights[z,x];RequireFinite(value);if(value<0||value>1)issues.Add("Height outside actual normalized range.");
                    if(x>0&&z>0&&x<n-1&&z<n-1)continue;float wx=p.x+s.x*x/(n-1),wz=p.z+s.z*z/(n-1),y=p.y+value*s.y;
                    if(OnInnerBoundary(wx,wz)){result.innerSamples++;result.innerMaximumError=Mathf.Max(result.innerMaximumError,Mathf.Abs(y-SampleInner(inner,wx,wz)));}
                    if(Mathf.Abs(wx+2400)<.001f||Mathf.Abs(wx-2400)<.001f||Mathf.Abs(wz+1600)<.001f||Mathf.Abs(wz-3200)<.001f){result.bedSamples++;result.bedMaximumError=Mathf.Max(result.bedMaximumError,Mathf.Abs(y-Bed));}
                    string key=Key(wx,wz);if(!vertices.TryGetValue(key,out var values)){values=new List<float>();vertices.Add(key,values);}values.Add(y);
                }
            }
            foreach(var values in vertices.Values)if(values.Count>1){result.outerSamples+=values.Count;result.outerMaximumError=Mathf.Max(result.outerMaximumError,values.Max()-values.Min());}
            if(result.innerSamples<2000||result.outerSamples<2000||result.bedSamples<6000)issues.Add("Actual inner/outer/bed sample coverage incomplete.");
            if(result.innerMaximumError>SeamTolerance)issues.Add("Measured inner edge seam exceeds.04m: "+result.innerMaximumError);
            if(result.outerMaximumError>SeamTolerance)issues.Add("Measured new shared edge seam exceeds.04m: "+result.outerMaximumError);
            if(result.bedMaximumError>SeamTolerance)issues.Add("Actual vendor coastal bed differs from−8m by more than.04m: "+result.bedMaximumError);
            result.issues=issues.Distinct().ToArray();return result;
        }

        static Terrain[] ReadInner(GameObject root)
        {
            if(root==null)throw new ArgumentNullException(nameof(root));return ValidateInner(root.GetComponentsInChildren<Terrain>(true));
        }
        static Terrain[] ValidateInner(Terrain[] tiles)
        {
            if(tiles==null||tiles.Length!=4||tiles.Any(t=>t==null)||tiles.Distinct().Count()!=4)throw new InvalidOperationException("Exact four distinct actual accepted inner Terrain components required.");
            foreach(float x in new[]{-1600f,0})foreach(float z in new[]{-800f,800})
            {
                var t=tiles.SingleOrDefault(v=>Vector3.Distance(v.transform.position,new Vector3(x,BaseY,z))<.001f);
                if(t==null||t.terrainData==null||t.terrainData.size!=new Vector3(1600,Height,1600)||t.terrainData.heightmapResolution!=513||t.transform.lossyScale!=Vector3.one||Quaternion.Angle(t.transform.rotation,Quaternion.identity)>.001f)
                    throw new InvalidOperationException("Actual accepted inner origins/size/513samples must match the measured factory contract.");
            }
            return tiles;
        }
        static float SampleInner(Terrain[] inner,float x,float z)
        {
            float sum=0;int count=0;
            foreach(var t in inner){var p=t.transform.position;var s=t.terrainData.size;if(x>=p.x-.001f&&x<=p.x+s.x+.001f&&z>=p.z-.001f&&z<=p.z+s.z+.001f){sum+=p.y+t.terrainData.GetInterpolatedHeight(Mathf.Clamp01((x-p.x)/s.x),Mathf.Clamp01((z-p.z)/s.z));count++;}}
            if(count==0)throw new InvalidOperationException("Measured collar sample outside exact inner terrain.");return sum/count;
        }
        static bool OnInnerBoundary(float x,float z)=>((Mathf.Abs(x+1600)<.001f||Mathf.Abs(x-1600)<.001f)&&z>=-800-.001f&&z<=2400+.001f)||((Mathf.Abs(z+800)<.001f||Mathf.Abs(z-2400)<.001f)&&x>=-1600-.001f&&x<=1600+.001f);
        static string Key(float x,float z)=>Mathf.RoundToInt(x*16)+":"+Mathf.RoundToInt(z*16);
        static void LinkOuterNeighbors(Terrain[] tiles)
        {
            foreach(var t in tiles)
            {
                var p=t.transform.position;var s=t.terrainData.size;
                Terrain At(float x,float z)=>tiles.SingleOrDefault(v=>Mathf.Abs(v.transform.position.x-x)<.001f&&Mathf.Abs(v.transform.position.z-z)<.001f);
                var left=tiles.SingleOrDefault(v=>Mathf.Abs(v.transform.position.x+v.terrainData.size.x-p.x)<.001f&&Mathf.Abs(v.transform.position.z-p.z)<.001f);
                var bottom=tiles.SingleOrDefault(v=>Mathf.Abs(v.transform.position.z+v.terrainData.size.z-p.z)<.001f&&Mathf.Abs(v.transform.position.x-p.x)<.001f);
                t.SetNeighbors(left,At(p.x,p.z+s.z),At(p.x+s.x,p.z),bottom);
            }
        }
        static Dictionary<string,string> Snapshot(IEnumerable<string> roots)=>roots.Where(p=>AssetDatabase.LoadMainAssetAtPath(p)!=null).SelectMany(p=>AssetDatabase.GetDependencies(p,true)).SelectMany(p=>new[]{p,p+".meta"}).Where(p=>File.Exists(Io(p))).Distinct().ToDictionary(p=>p,p=>Hash(File.ReadAllBytes(Io(p))));
        static string HeightHash(float[,] heights){var bytes=new byte[heights.Length*sizeof(float)];Buffer.BlockCopy(heights,0,bytes,0,bytes.Length);return Hash(bytes);}
        static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
        static string Io(string path){string full=Path.GetFullPath(path);return Application.platform==RuntimePlatform.WindowsEditor&&full.Length>=248&&!full.StartsWith(@"\\?\",StringComparison.Ordinal)?@"\\?\"+full:full;}
        static void RequireFinite(float value){if(float.IsNaN(value)||float.IsInfinity(value))throw new InvalidOperationException("Nonfinite actual Vista terrain sample.");}
        static void RequireTag(string tag){if(string.IsNullOrEmpty(tag)||tag.Length>40||tag.Any(c=>!char.IsLetterOrDigit(c)&&c!='-'&&c!='_'))throw new ArgumentException("Bounded exact candidate tag required.");}
        static string Arg(string flag,string fallback){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,flag);return i>=0&&i+1<args.Length?args[i+1]:fallback;}
    }
}
